function initial(){return {version:1,started:false,seen:[],done:[],turn:0,loss:false,service:100,hints:0,hypothesis:'',finished:false,log:[],lab:{mfa:false,rule:false,ran:false,attempts:0},mode:'learn'};}
function add(s,text){s.log.push({turn:s.turn,text});}
function tick(s){s.turn++;if(s.turn>=8&&!s.done.includes('revoke')&&!s.done.includes('shutdown')&&!s.loss){s.loss=true;add(s,'ผู้โจมตีดาวน์โหลดรายงาน 12 รายการก่อนถูกตัดเซสชัน');}}
function inspect(s,id){if(s.finished||s.seen.includes(id)||!evidence.some(e=>e.id===id))return s;s.seen.push(id);tick(s);add(s,'ตรวจหลักฐาน: '+evidence.find(e=>e.id===id).name);return s;}
function act(s,id){const a=actions.find(a=>a.id===id);if(!a||s.finished||s.done.includes(id))return {ok:false,message:'ดำเนินการนี้แล้ว หรือภารกิจจบแล้ว'};if(a.need.some(x=>!s.seen.includes(x)))return {ok:false,message:'ตรวจหลักฐานที่เกี่ยวข้องก่อน: '+a.need.filter(x=>!s.seen.includes(x)).map(x=>evidence.find(e=>e.id===x).name).join(', ')};if(id==='verify'&&!['revoke','reset','rule','purge'].every(x=>s.done.includes(x)))return {ok:false,message:'ยังยืนยันไม่ได้: ต้องตัดเซสชัน จัดการรหัสผ่าน ลบกฎส่งต่อ และกักกันอีเมลก่อน'};s.done.push(id);s.service=Math.max(0,s.service-a.cost);tick(s);add(s,a.title);return {ok:true,message:id==='verify'?'ตรวจยืนยันแล้ว: เซสชันเดิมถูกปฏิเสธ ไม่มีกฎส่งต่อผิดปกติ และกักกันอีเมลครบ':a.title+' — ดำเนินการแล้ว'};}
function score(s){const diagnosis=(s.hypothesis==='takeover'?15:0)+Math.round(s.seen.filter(x=>x!=='backup').length*2);const containment=(s.done.includes('revoke')?20:0)+(s.loss?0:5);const repair=['reset','rule','purge','verify'].filter(x=>s.done.includes(x)).length*10;const continuity=Math.round(s.service*.1);return {diagnosis,containment,repair,continuity,total:diagnosis+containment+repair+continuity};}
function outcome(s){if(!s.done.includes('revoke')||!s.done.includes('reset'))return 'ยังมีช่องทางเข้าถึงบัญชี';if(!s.done.includes('rule')||!s.done.includes('purge'))return 'หยุดบัญชีได้ แต่ยังมีความเสี่ยงค้างอยู่';if(!s.done.includes('verify'))return 'แก้ไขแล้ว แต่ยังไม่ได้ตรวจยืนยัน';if(s.loss)return 'ควบคุมเหตุได้หลังข้อมูลบางส่วนรั่วไหล';if(s.service<100)return 'ควบคุมเหตุได้ แต่บริการได้รับผลกระทบ';return 'ควบคุมเหตุสำเร็จ รักษาบริการได้';}
